import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Queue;
import java.util.Set;

class Solution {
    public int minMutation(String startGene, String endGene, String[] bank) {
        if (startGene.equals(endGene)) return 0;
        Set<String> allowed = new HashSet<>(Arrays.asList(bank));
        if (!allowed.contains(endGene)) return -1;
        List<String> genes = new ArrayList<>(allowed);
        if (!allowed.contains(startGene)) genes.add(startGene);
        List<List<Integer>> graph = new ArrayList<>();
        for (int index = 0; index < genes.size(); index++) graph.add(new ArrayList<>());
        for (int first = 0; first < genes.size(); first++) {
            for (int second = first + 1; second < genes.size(); second++) {
                if (oneChange(genes.get(first), genes.get(second))) { graph.get(first).add(second); graph.get(second).add(first); }
            }
        }
        int start = genes.indexOf(startGene), target = genes.indexOf(endGene);
        int[] distance = new int[genes.size()]; Arrays.fill(distance, -1);
        Queue<Integer> queue = new ArrayDeque<>(); distance[start] = 0; queue.offer(start);
        while (!queue.isEmpty()) {
            int current = queue.poll();
            if (current == target) return distance[current];
            for (int next : graph.get(current)) if (distance[next] == -1) { distance[next] = distance[current] + 1; queue.offer(next); }
        }
        return -1;
    }
    private boolean oneChange(String first, String second) {
        int differences = 0;
        for (int index = 0; index < first.length(); index++) if (first.charAt(index) != second.charAt(index) && ++differences > 1) return false;
        return differences == 1;
    }
}

