import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Queue;
import java.util.Set;

class Solution {
    public int minMutation(String startGene, String endGene, String[] bank) {
        if (startGene.equals(endGene)) return 0;
        Set<String> unvisited = new HashSet<>(Arrays.asList(bank));
        if (!unvisited.contains(endGene)) return -1;
        char[] alphabet = {'A', 'C', 'G', 'T'};
        Queue<String> queue = new ArrayDeque<>();
        queue.offer(startGene);
        int mutations = 0;
        while (!queue.isEmpty()) {
            int levelSize = queue.size();
            for (int count = 0; count < levelSize; count++) {
                char[] current = queue.poll().toCharArray();
                for (int index = 0; index < current.length; index++) {
                    char original = current[index];
                    for (char replacement : alphabet) {
                        if (replacement == original) continue;
                        current[index] = replacement;
                        String candidate = new String(current);
                        if (candidate.equals(endGene)) return mutations + 1;
                        if (unvisited.remove(candidate)) queue.offer(candidate);
                    }
                    current[index] = original;
                }
            }
            mutations++;
        }
        return -1;
    }
}
